// ------------------------------------------------------------------ constructeurs de catalogue
function C(string $key, string $label, string $mode = 'fixed', $value = 0, array $x = []): array { return ['key' => $key, 'label' => $label, 'price' => ['mode' => $mode, 'value' => $value]] + $x; }
function G(string $key, string $label, string $type, array $choices, ?string $default = null, array $o = []): array {
    return ['key' => $key, 'label' => $label, 'type' => $type, 'required' => $o['required'] ?? true, 'default' => $default ?? $choices[0]['key'], 'help' => $o['help'] ?? '', 'choices' => $choices, 'show_if' => $o['show_if'] ?? null];
}
function g_faces(int $pct = 30): array { return G('faces', 'Impression', 'radio', [C('recto', 'Recto seul (4/0)'), C('rv', 'Recto-verso (4/4)', 'percent', $pct)]); }
function g_finish(): array { return G('finition', 'Finition', 'radio', [C('none', 'Sans finition'), C('mat', 'Pelliculage mat', 'percent', 22), C('brillant', 'Pelliculage brillant', 'percent', 22), C('softtouch', 'Pelliculage soft-touch', 'percent', 45, ['badge' => 'Premium']), C('vsel', 'Vernis sélectif UV', 'percent', 70)]); }
function g_verif(): array { return G('verif', 'Vérification des fichiers', 'radio', [C('none', 'Sans vérification'), C('expert', 'Vérification par un expert', 'fixed', 2000, ['desc' => 'Nous contrôlons votre fichier avant impression'])], 'none', ['required' => false]); }
function g_creation(): array { return G('creation', 'Création graphique', 'radio', [C('none', "J'ai mon fichier prêt"), C('creation', 'Symo Print crée mon visuel', 'fixed', 15000, ['desc' => 'Tarif indicatif, confirmé après briefing'])], 'none', ['required' => false]); }
function delays(array $std = [3, 5], array $exp = [1, 2], int $expPct = 30, int $urgPct = 60): array {
    return [['key' => 'standard', 'label' => 'Standard', 'days' => $std, 'percent' => 0], ['key' => 'express', 'label' => 'Express', 'days' => $exp, 'percent' => $expPct], ['key' => 'urgent', 'label' => 'Urgent (24 h)', 'days' => [1, 1], 'percent' => $urgPct]];
}
function FI(string $text): string { return '<ul><li>' . implode('</li><li>', array_map('e', explode('|', $text))) . '</li></ul>'; }
const FI_STD = 'Format PDF recommandé (TIFF, EPS, PNG, JPG acceptés)|Résolution 300 dpi au format final|Mode CMJN, polices vectorisées|Fond perdu : 3 mm autour du format fini|Marge de sécurité : 5 mm à l\'intérieur';
const FI_BIG = 'Format PDF recommandé (TIFF, EPS, PNG, JPG acceptés)|Résolution 100 à 150 dpi à la taille finale|Mode CMJN, polices vectorisées|Fond perdu : 5 mm autour du format fini|Textes à 10 cm au moins du bord pour les œillets';
const FI_OBJ = 'Logo vectoriel (PDF, AI, EPS, SVG) idéal, PNG haute définition accepté|Indiquez les couleurs souhaitées (Pantone si disponible)|Fournissez le texte exact à graver ou imprimer';

function P(string $cat, string $slug, string $name, string $short, array $o): void {
    static $ids = []; if (!$ids) foreach (DB::all('SELECT id, slug FROM categories') as $r) $ids[$r['slug']] = (int) $r['id'];
    $model = $o['model'] ?? 'tiers';
    $pricing = $model === 'area' ? $o['area'] : ['tiers' => $o['tiers'], 'min_total' => $o['min_total'] ?? 0];
    $qp = $o['qty'] ?? [1, 5, 10, 25, 50];
    $row = ['category_id' => $ids[$cat] ?? 0, 'slug' => $slug, 'name' => $name, 'short_desc' => $short, 'description' => $o['desc'] ?? '', 'image' => $o['image'] ?? '',
        'gallery' => je($o['gallery'] ?? []), 'icon' => $o['icon'] ?? 'flyer', 'pricing_model' => $model, 'pricing' => je($pricing),
        'qty_cfg' => je(['presets' => $qp, 'min' => $o['qmin'] ?? min($qp), 'max' => $o['qmax'] ?? 100000, 'step' => $o['qstep'] ?? 1, 'default' => $o['qdef'] ?? ($qp[min(2, count($qp) - 1)]), 'unit' => $o['unit'] ?? 'ex.']),
        'groups_json' => je($o['groups'] ?? []), 'delays' => je($o['delays'] ?? delays()), 'file_info' => FI($o['fi'] ?? FI_STD), 'file_required' => $o['file_required'] ?? 1,
        'featured' => $o['featured'] ?? 0, 'bestseller' => $o['best'] ?? 0, 'is_new' => $o['new'] ?? 0, 'promo_label' => $o['promo'] ?? '', 'pricing_status' => 'demo',
        'keywords' => $o['kw'] ?? '', 'sort' => $o['sort'] ?? 0, 'updated_at' => now()];
    $id = DB::ins('products', $row);
    $p = DB::find('products', $id); DB::upd('products', $id, ['price_from' => Pricing::from($p)]);
}

